function CatalogoQD.buscarPorNome(nome)
    for _, item in ipairs(CatalogoQD.itens) do
        if item.nome == nome then return item end
    end
    return nil
end

function CatalogoQD.listarPorTipo(tipo)
    local lista = {}
    for _, item in ipairs(CatalogoQD.itens) do
        if item.tipo == tipo then table.insert(lista, item) end
    end
    table.sort(lista, function(a, b) return a.nome < b.nome end)
    return lista
end

function CatalogoQD.somarEfeitos(escolhidos)
    local total = {apPercent = 0, hpPercent = 0}
    for _, esc in ipairs(escolhidos or {}) do
        local item = CatalogoQD.buscarPorNome(esc.nome)
        if item ~= nil and item.efeitos ~= nil then
            local mods = item.efeitos[tonumber(esc.pontos) or 0]
            if mods ~= nil then
                for chave, valor in pairs(mods) do
                    total[chave] = (total[chave] or 0) + valor
                end
            end
        end
    end
    return total
end

return CatalogoQD
